const menu=document.querySelector('.menu-button'),mobileMenu=document.querySelector('#mobile-menu');let menuScrollY=0;
function setMenuOpen(open,restoreFocus=false){const wasOpen=menu.getAttribute('aria-expanded')==='true';if(open===wasOpen)return;menu.setAttribute('aria-expanded',String(open));mobileMenu.hidden=!open;menu.textContent=open?'Close':'Menu';if(open){menuScrollY=window.scrollY;document.body.style.setProperty('--menu-scroll-offset',`-${menuScrollY}px`);document.body.classList.add('menu-open');document.documentElement.classList.add('menu-open');document.querySelector('.header').classList.remove('hide-header')}else{document.body.classList.remove('menu-open');document.documentElement.classList.remove('menu-open');document.body.style.removeProperty('--menu-scroll-offset');window.scrollTo({top:menuScrollY,behavior:'instant'});if(restoreFocus)menu.focus()}document.querySelectorAll('main,footer').forEach(element=>element.inert=open)}
menu.addEventListener('click',()=>setMenuOpen(menu.getAttribute('aria-expanded')!=='true'));
mobileMenu.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>setMenuOpen(false)));
document.addEventListener('keydown',event=>{if(mobileMenu.hidden)return;if(event.key==='Escape'){event.preventDefault();setMenuOpen(false,true)}else if(event.key==='Tab'){const items=[menu,...mobileMenu.querySelectorAll('a')],first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});
window.addEventListener('pageshow',()=>setMenuOpen(false));

const header=document.querySelector('.header');let lastScroll=window.scrollY;window.addEventListener('scroll',()=>{const current=window.scrollY;if(Math.abs(current-lastScroll)>6){header.classList.toggle('hide-header',current>lastScroll&&current>180&&mobileMenu.hidden);lastScroll=current}},{passive:true});header.addEventListener('focusin',()=>header.classList.remove('hide-header'));
const carousel=document.querySelector('.application-stage');
if(carousel){const slides=[{name:'Cosmetics',image:'cream',alt:'Close-up photograph of cosmetic cream',title:'Advanced polymers<br>for cosmetics.',description:'Cosmetic performance with bio-sourced and biodegradable ingredients.',path:'cosmetics'},{name:'Transportation',image:'aviation',alt:'A close view of an aircraft engine',title:'Lightweight structures.<br>Advanced batteries.',description:'Explore polymers for lightweight structures, battery materials, coatings and passenger comfort.',path:'transportation'},{name:'Electronics',image:'electronics',alt:'Components on a printed circuit board',title:'Polymers for<br>advanced electronics.',description:'Explore polymers for thermal management, electrical insulation and protection in electronic applications.',path:'electronics'}];let current=0;function change(i){current=(i+slides.length)%slides.length;const s=slides[current];const image=carousel.querySelector('.slide-photo');image.src='/assets/'+s.image+'.webp';image.alt=s.alt;document.querySelector('#slide-title').innerHTML=s.title;document.querySelector('#slide-description').textContent=s.description;const l=document.querySelector('#slide-link');l.href='/applications/'+s.path+'/';l.textContent='Explore '+s.name.toLowerCase();carousel.querySelectorAll('[data-slide]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.slide)===current)))}carousel.querySelectorAll('[data-slide]').forEach(b=>b.addEventListener('click',()=>change(Number(b.dataset.slide))));carousel.querySelectorAll('[data-carousel]').forEach(b=>b.addEventListener('click',()=>change(current+(b.dataset.carousel==='next'?1:-1))));carousel.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();change(current+1)}else if(e.key==='ArrowLeft'){e.preventDefault();change(current-1)}})}
const form=document.querySelector('#enquiry-form');if(form){const params=new URLSearchParams(location.search);const application=params.get('application');if(application){const select=form.elements.application;[...select.options].forEach(o=>{if(o.value.toLowerCase()===application.toLowerCase())select.value=o.value})}const route=params.get('route'),routeNames={'1':'Sample synthesis and testing','2':'AI-driven polymer development','3':'Application domain exploration'};if(routeNames[route])form.elements.challenge.value='Interested in '+routeNames[route]+'.\n\n';form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const subject='Material enquiry — '+data.get('company');const body='Name: '+data.get('name')+'\nCompany: '+data.get('company')+'\nEmail: '+data.get('email')+'\nApplication: '+(data.get('application')||'To discuss')+'\n\nMaterial challenge:\n'+data.get('challenge');const href='mailto:contact@synboli.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);const status=document.querySelector('#form-status');status.replaceChildren();const p=document.createElement('span');p.textContent='Your email draft is ready. If your email app did not open, ';const a=document.createElement('a');a.href=href;a.textContent='open the prepared email';a.style.textDecoration='underline';status.append(p,a);window.location.href=href})}

const processTabs=[...document.querySelectorAll('.process-tabs [role="tab"]')],processPanels=[...document.querySelectorAll('.process-panel')];if(processTabs.length&&processTabs.length===processPanels.length){function selectProcess(index,focus=false){processTabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===index));tab.tabIndex=i===index?0:-1;const panel=processPanels[i];panel.hidden=i!==index;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',tab.id)});if(focus)processTabs[index].focus()}processTabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectProcess(index));tab.addEventListener('keydown',event=>{let target=index;if(event.key==='ArrowRight')target=(index+1)%processTabs.length;else if(event.key==='ArrowLeft')target=(index+processTabs.length-1)%processTabs.length;else if(event.key==='Home')target=0;else if(event.key==='End')target=processTabs.length-1;else return;event.preventDefault();selectProcess(target,true)})});document.querySelector('.process-panels').classList.add('process-ready');selectProcess(0)}

const desktopNavigation=window.matchMedia('(min-width: 981px)');desktopNavigation.addEventListener('change',event=>{if(event.matches){setMenuOpen(false);header.classList.remove('hide-header')}});
